{
  "implementation": "def solve(case):
    edges = case['payload']['edges']
    refinement = case['payload']['refinement']
    membership = {}
    for node, group in refinement.items():
        membership.setdefault(group, []).append(node)
    for group in membership:
        membership[group].sort()
    sorted_groups = sorted(membership.keys())
    membership_lists = [membership[g] for g in sorted_groups]
    agg = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        a, b = (gu, gv) if gu <= gv else (gv, gu)
        agg[(a, b)] = agg.get((a, b), 0) + w
    aggregate_edges = sorted([list(k) + [v] for k, v in agg.items()])
    return {'aggregate_edges': aggregate_edges, 'membership_lists': membership_lists}"
}
